create extension if not exists pgcrypto;
create type public.app_role as enum ('student','teacher','admin');
create type public.inquiry_status as enum ('new','contacted','trial_scheduled','enrolled','closed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'student',phone text,country text,created_at timestamptz default now());
create table public.courses(id uuid primary key default gen_random_uuid(),title text not null unique,description text,active boolean not null default true,created_at timestamptz default now());
create table public.inquiries(id uuid primary key default gen_random_uuid(),name text not null,email text not null,country text not null,course text not null,contact text not null,age integer,message text,status public.inquiry_status not null default 'new',created_at timestamptz default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid not null references public.courses(id),teacher_id uuid references public.profiles(id),status text not null default 'active',created_at timestamptz default now());
create table public.class_sessions(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,teacher_id uuid references public.profiles(id),course_id uuid references public.courses(id),starts_at timestamptz not null,duration_minutes integer not null default 30,zoom_url text,status text not null default 'scheduled',created_at timestamptz default now());
create table public.attendance(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.class_sessions(id) on delete cascade,student_id uuid not null references public.profiles(id),status text not null check(status in('present','absent','late','excused')),notes text,recorded_by uuid references public.profiles(id),created_at timestamptz default now(),unique(session_id,student_id));
create table public.progress_reports(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),teacher_id uuid references public.profiles(id),course_id uuid references public.courses(id),lesson_topic text not null,strengths text,next_steps text,created_at timestamptz default now());
create table public.fee_records(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),amount numeric(10,2) not null,currency text not null default 'USD',due_date date,paid_at timestamptz,status text not null default 'pending',notes text,created_at timestamptz default now());
create function public.new_user_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'student');return new;end;$$;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_user_profile();
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin');$$;
create function public.is_assigned_teacher(sid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.enrollments where student_id=sid and teacher_id=auth.uid());$$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','courses','inquiries','enrollments','class_sessions','attendance','progress_reports','fee_records'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "profile read self admin" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin() or public.is_assigned_teacher(id));
-- Self-service role changes are intentionally disabled to prevent privilege escalation.
create policy "admin all profiles" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public read active courses" on public.courses for select using(active or public.is_admin());
create policy "admin manage courses" on public.courses for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public submit inquiries" on public.inquiries for insert to anon,authenticated with check(status='new');
create policy "admin read inquiries" on public.inquiries for select to authenticated using(public.is_admin());
create policy "admin update inquiries" on public.inquiries for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "enrollment participants read" on public.enrollments for select to authenticated using(student_id=auth.uid() or teacher_id=auth.uid() or public.is_admin());
create policy "admin manage enrollments" on public.enrollments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "class participants read" on public.class_sessions for select to authenticated using(student_id=auth.uid() or teacher_id=auth.uid() or public.is_admin());
create policy "admin manage classes" on public.class_sessions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "assigned teacher manage classes" on public.class_sessions for all to authenticated using(teacher_id=auth.uid()) with check(teacher_id=auth.uid());
create policy "attendance participant read" on public.attendance for select to authenticated using(student_id=auth.uid() or public.is_admin() or public.is_assigned_teacher(student_id));
create policy "admin teacher attendance" on public.attendance for all to authenticated using(public.is_admin() or public.is_assigned_teacher(student_id)) with check(public.is_admin() or public.is_assigned_teacher(student_id));
create policy "progress participant read" on public.progress_reports for select to authenticated using(student_id=auth.uid() or teacher_id=auth.uid() or public.is_admin());
create policy "admin teacher progress" on public.progress_reports for all to authenticated using(public.is_admin() or teacher_id=auth.uid()) with check(public.is_admin() or teacher_id=auth.uid());
create policy "student admin fee read" on public.fee_records for select to authenticated using(student_id=auth.uid() or public.is_admin());
create policy "admin manage fees" on public.fee_records for all to authenticated using(public.is_admin()) with check(public.is_admin());
